const frmNm = "view_voucher"


const productListOn = "productListOnVoucherCmp"

const productListSelectedCollection = "productList2VoucherSelected"


let flds = ["clientAddress",
	"clientName",
	"date",
	"invoice",
	"locProdFinish",
	"products",
	"userId",
	"voucherId"  ]

//let hhhhh = [{"productId":"hH2lVnw7JAiY0Ulg","unit":"S/F","qty":"1","profile":"COBE","inventoryId":"kYrHYgG11eflsVeJ","alphaCode":"MT-2548","date":1697818423967,"bluePrint":{"type":"U","vertices":{"1":{"vertice":1,"isWall":1,"width":92,"profile":null},"2":{"vertice":2,"needProfile":1,"width":24,"profile":"COBE"},"3":{"vertice":3,"isWall":1,"width":52,"profile":null},"4":{"vertice":4,"width":24,"needProfile":1,"profile":"COBE"},"5":{"vertice":5,"needProfile":1,"profile":"COBE"},"6":{"vertice":6,"isWall":1,"profile":null},"8":{"vertice":8,"width":24,"needProfile":1,"profile":"COBE"},"sink":{"vertice":"sink","needProfile":1,"width":28,"height":18,"xPos":32,"yPos":"6","profile":"COBE"}}}},{"productId":"P9ZnIAVrEq3zI1aJ","unit":"Uno","qty":"1","inventoryId":"ZANy7sILcOpt2QvF","alphaCode":"MT-0072","date":1697818507142},{"productId":"ohQordOGWnhgRpIF","unit":"S/F","qty":"1","profile":"PENCIL","inventoryId":"EQrhQWOhHSEAWvJB","alphaCode":"MT-4886","date":1697818569508,"bluePrint":{"type":"LL","vertices":{"1":{"vertice":1,"needProfile":0,"isWall":1,"width":92,"profile":null},"2":{"vertice":2,"width":24,"needProfile":1,"profile":"PENCIL"},"3":{"vertice":3,"isWall":1,"width":52,"profile":null},"4":{"vertice":4,"needProfile":1,"width":24,"profile":"PENCIL"},"5":{"vertice":5,"needProfile":1,"profile":"PENCIL"},"6":{"vertice":6,"isWall":1,"profile":null},"sink":{"vertice":"sink","needProfile":1,"width":28,"height":18,"xPos":32,"yPos":"6","profile":"PENCIL"}}}}]

const ViewVoucher  = ({ data, confirm, updateView, voucherItem }) => {
	const [initialize, setInitialize] = useState(false);
	const [obs, set_obs] = useState(0);

	const navigate = useNavigate();

	useEffect(() => {
		if (!initialize) {
			setInitialize(true);
			updStore("accountPicker", {});
			set_obs(gen16CodeId())
		}
	});

	const updFrm = (f, v, k) => {
		let frm2 = getStore(frmNm) || {};
		if(k){
			if( !frm2[k]){
				frm2[k] = {};
			}
			frm2[k][f] = v;
		}else{
			frm2[f] = v;
		}
		updStore(frmNm, frm2);
		
		set_obs(gen16CodeId())
	};

	const printInvLbs = async () => {
		updStore("bluePrint",null)
		let frm2 = getStore(frmNm) || {};

		let obj2Prnt = {
			invoice: frm2?.invoice,
			date: frm2?.date,
			clientAddress: frm2?.clientAddress,
			clientName: frm2?.clientName,
			products: []
		}

		
		let date = (new Date()).getTime()+800;
		if(obj2Prnt["date"]){
			let nn = (new Date(obj2Prnt["date"])).getTime();
			date = nn?nn:date;
		}
		obj2Prnt["date"] = date; 



		const promises = getStore(productListOn) && getStore(productListOn).map(async (item) => {
			let productD = getStore("products_ids")?.[item?.productId];
			let nOvj = {}
			nOvj["productName"] = productD?.name;
			nOvj["qty"] = item?.qty*1;
			nOvj["profile"] = item?.profile;
			if(item?.bluePrint?.type){
				let gg = document.getElementById(item.productId +"_"+ item?.bluePrint?.type);
				let dataUrl = await htmlToImage.toPng(gg);
				
				nOvj["pngId"] = dataUrl;
			}
			obj2Prnt.products.push(nOvj);
		})
		const contents = await Promise.all(promises);
	
		let pdfUri = await VoucherPdf(obj2Prnt);


		//let pdfUri = await generateTemp("I485_form.pdf", 1)
		// setLoadPrint(false)
		window.open(pdfUri);
	}

	const save  = async ()  => {
		let frm2 = getStore(frmNm) || {};

		let diff = compareJSON(flds,frm2,getStore(frmNm + "_bck") )

		let bdyq2 = {...getStore(qryStore())?.upd_voucher_production};
		bdyq2.params = {
			businessId:  getStore("profileUser")?.businessId,
			voucherId: frm2.voucherId
		}
		bdyq2.data2update= diff.data;
		
		fetchApi(bdyq2);


	}

	const fetchApi  = async (bdyq2)  => {
		
		
		const res = fetchEncryptStream(bdyq2);
		const td = await res;
		if (td) {
			updStore(frmNm, {});
			updStore(frmNm + "_bck", {});
			set_obs(gen16CodeId());
			confirm && confirm();
			data?.modalID && CloseModal({id:data?.modalID})
		}
	}



	const updlocDrop  = async (v, rmv)  => {
		let itm2 = getStore(frmNm) || {};
		let locProdFinish = itm2?.["locProdFinish"] || {};
		if(rmv){
			locProdFinish[v] = 0;
			//delete locProdFinish[v]
		}else{
			locProdFinish[v.id] = 1;
		}
		itm2.locProdFinish = locProdFinish;
		updStore(frmNm,itm2);

		//let diff2 = compareJSON(flds,itm2, getStore(frmNm + "_bck") )
		
		set_obs(gen16CodeId());
	}


	const locationFunct  = async (v)  => {
		return filterLocation(getStore("location_drpdwn"), v);
	}

	const updList  = async (products)  => {
		
		let frm2 = getStore(frmNm) || {};
		frm2.products = products;
		updStore(frmNm,frm2);
		set_obs(gen16CodeId());
	}


	
	const confirmFinished  = async ()  => {
		let frm2 = getStore(frmNm) || {};

	
		let bdyq2 = {...getStore(qryStore())?.upd_voucher_production};
		bdyq2.params = {
			businessId:  getStore("profileUser")?.businessId,
			voucherId: frm2.voucherId
		}
		bdyq2.data2update= {voucherStatus: 99};
		
		fetchApi(bdyq2);


	}

	const OpenMarkAsInstalled =  () => {
		let lastTimeCallModal = getStore("lastTimeCallModal") || 0;
		if(hasWritePrivilege() && !AccountYears()[getStore("date_current_year")]?.isClosed){
			if( Date.now() > lastTimeCallModal){
				updStore("lastTimeCallModal", Date.now()+320);
				let modaldata = {};
				modaldata["zIndex"] = 450;
				modaldata["height"] = "40vh";
				// data['observeResize']=true;
				modaldata["props"] = { minHeight: "1vh", overlay: true, closeEvent: ()=>{}  };
				let msg = <div className="_dsplFlx ">
						<span>
							Desea marcar el voucher como entregado
						</span>
					</div>
				modaldata["content"] = 
				<AlertScanningInventory
					msg={msg}
					title={"Esta seguro que? "}
					confirm={confirmFinished}
				/>
				OpenModal(modaldata);
			}
		}else{
			let modaldata = {};
			modaldata["zIndex"] = 450;
			modaldata["height"] = "40vh";
			// data['observeResize']=true;
			modaldata["props"] = { minHeight: "1vh", overlay: true, closeEvent: ()=>{}  };
			modaldata["content"] = <NoPrivilege />
			OpenModal(modaldata);
		}
	}

	let diff = compareJSON(flds,getStore(frmNm), getStore(frmNm + "_bck") )


	return (
		<div style={{
			maxHeight: "96vh",
			minHeight:  "93vh",
			width: "1060px",
			overflow: "auto",
			background: "var(--hrm_palette-general-background-b)",
			borderRadius: 13,
			padding: "10px 19px"
		}}>
			<div className="_dsplFlx ">
				<p className="form_title">
					Voucher
				</p>
				<div className="flexSpace"/>
				<p className="label">Invoice</p>
				<div className="date2Upd" style={{padding: 7, fontSize:18}}>{getStore(frmNm)?.["invoice"]}</div>
				
			</div>

			<div className="_dsplFlx ">
				<p className="label">Fecha:</p>
				<div className="valueFontC9" >{parseDateMMDDYYYY(getStore(frmNm)?.["date"])}</div>
				

				<div className="flexSpace"/>
				{getStore(frmNm)?.voucherStatus !==99 ? 
				
				<button onClick={OpenMarkAsInstalled}>
					Instalado
				</button>
				:
				<div className="date2Upd" style={{padding: 7, fontSize:18}}>{"Instalado"}</div>
				}
			</div>
			
			
	
			<ProductsBox 
				list={getStore(frmNm)?.["products"]} 
				updList={updList}
			/>

		
			<div className="_dsplFlx ">
				<div className="flexSpace"/>
				<p className="label">Locaciones del trabajo terminado:</p>
				<div className="flexSpace"/>
				{getStore(frmNm)?.voucherStatus !==99 ? AccountYears()[getStore("date_current_year")]?.isClosed?null:
				<div className="_dsplFlx spaceAround"  style={{padding: 3}}>
					<DropDwnPickerSearchComponent
						//init={invtag}
						lbl_empty={"Location"} 
						func={locationFunct} 
						onSelect={(e)=>updlocDrop(e)}
						background={"#f9f9f9"}
						color={"var(--hrm_palette-blue-purple)"}
						direction={"left"}
						width={"280px"}
					/>
				</div>
				:null}
				<div className="flexSpace"/>
			</div>
			<div className={""}>
				{getStore(frmNm)?.["locProdFinish"]  && ObjectKeys(getStore(frmNm)?.["locProdFinish"])?.map((locId, indE)=>{
					let locItm = getStore("locations_ids")?.[locId];
					let locFnsh = getStore(frmNm)?.["locProdFinish"]?.[locId];
					
					if(!locFnsh){
						return null;
					}
					return (
						<LocationKart key={locId} locId={locId} locItm={locItm} updlocDrop={updlocDrop} />

					)
				})}	
			</div>

			<div className="separator"></div>
			
			<div className="_dsplFlx "  style={{margin: "2px 0"}}>
				<p className="label">Nombre Cliente:</p>
				<div className="valueFontC9" >{getStore(frmNm)?.["clientName"]}</div>
			</div>
			<div className="_dsplFlx "  style={{margin: "1px 0"}}>
				<p className="label">Direccion:</p>
				<div className="valueFontC9" >{getStore(frmNm)?.["clientAddress"]}</div>
			</div>

			
			

			{diff?.hasChange ?
			AccountYears()[getStore("date_current_year")]?.isClosed?null:
			<div className="card">
				<button onClick={save}>
					Actualizar
				</button>
			</div>
			:null}
			<div style={{padding: 20}}></div>
		</div>
	);
};

export default ViewVoucher;





const LocationKart = ({locId, locItm, updlocDrop}) => {


	const OpenDeleteAlert = () =>{
		updlocDrop(locId,1)

	}


	return(
		<div>
			<div className="_dsplFlx ">
			<div className="flexSpace"/>
				<div className="_dsplFlx centerBx locatKrt" >
					
					<div style={{padding: "0 7px"}} className=" centerBx" >
						{areasIds[locItm?.areaId]}
					</div>
					<div style={{padding: "0 7px"}} className="date2Upd centerBx" >
						{`${locItm?.areaId}-${locItm?.location}`}
					</div>
					<div className="flexSpace"/>
					{getStore(frmNm)?.voucherStatus !==99 ? 
					AccountYears()[getStore("date_current_year")]?.isClosed?null:
					<div className="icon centerBx" onClick={OpenDeleteAlert}>
						<Svg name={"outline_delete"} color={"#c62828"}/>
					</div>
					:null}
				</div>
				<div className="flexSpace"/>
			</div>
		</div>
	)
}


