const ProductsBox = ({list, updList}) => {
	const [obs, set_obs] = useState(0);

	const  updObs = () =>{
		set_obs(gen16CodeId())
    }
	
	const  updItem = (v) =>{
		
		let kk = "productId"
		let indX = filterLocationIndex(list,kk,v[kk]);
		let nList = list;
		nList[indX] = v;
		updList(nList)
		
    }
		



	return (
		
		<div className="boxAddAcc" style={{margin: "18px 0"}}>

			<div className="_dsplFlx hdr_bar purple align_itm" style={{margin: "18px 0"}}>
				
				<div className="tr_bar tr_bar_50 left_alg">
					Producto
				</div>
				<div className="tr_bar tr_bar_20">
					InventoryTag
				</div>
				<div className="tr_bar tr_bar_15">
					Qty
				</div>
				<div className="tr_bar tr_bar_15">
					Profile
				</div>
				
			</div>
			{list  && list.length > 0  && 
				list?.map((element, indE)=>
				<ListingProducts 
					key={element.productId +"_"+ indE} 
					idKey={element.productId}
					index={indE} 
					data={element}
					updObs={updObs}
					updItem={updItem}
				/>
			)}
		</div>

	)
}






const ListingProducts  = ({ data, updItem, updObs, index }) => {



	let productD = getStore("products_ids")?.[data?.productId];
	
	

	// const hoverRef = useRef(false);
	const overCompRef = useRef(null);

	const drawBox=(e)=>{
		
		// overCompRef?.current?.setAttribute("data-ved",e);
		overCompRef?.current?.showw(e);
		
	}




	const getIndex = (data,productId) => {
		let inD = null;
		data.map((dd,ii)=>{
			if( dd.productId === productId){
				inD = ii;
			}
		})
		return inD;
	}

	const AddBlPr2Prod = (v) => {

		let copyD = {...data};
		
		copyD.bluePrint =v;
		let productListOnCmp = getStore(productListOn);
		let ff = getIndex(productListOnCmp, copyD.productId);
		productListOnCmp[ff] = copyD;
		

		updStore(productListOn, productListOnCmp);
		updObs();
	}



	const closeMenu = () => {
		drawBox(false)
	}


	const updlocDrop =  (v) => {
		let nObj = {...data};
		nObj["inventoryId"]=v.id;
		nObj["alphaCode"]=v.label;	
		updItem(nObj)
		// updStore(f,v);
		// handle_search_movement();
	}

	const clearDrp =  (v) => {
		let nObj = {...data};
		nObj["inventoryId"]=null;
		nObj["alphaCode"]=null;	
		updItem(nObj)
		// updStore(f,v);
		// handle_search_movement();
	}

	return (
		<div className="_dsplFlx hdr_bar centerBx">
			
			<div className="tr_bar tr_bar_50 left_alg" >
				{productD?.name}
			</div>
			<div className="tr_bar tr_bar_20 centerBx" style={{marginTop:-4}}>
			{data?.inventoryId?
				<div style={{padding: "0 7px"}} className="date2Upd" onClick={clearDrp}>
					{data?.alphaCode}
				</div>
				:
				<div className="_dsplFlx spaceAround"  style={{padding: 3}}>
					{getStore(frmNm)?.voucherStatus !==99 ? 
					<DropDwnPickerSearchComponent
						init={data?.inventoryId}
						lbl_empty={"Inventory"} 
						func={getInventoryToDrpDwn} 
						onSelect={(e)=>updlocDrop(e)}
						background={"#f9f9f9"}
						color={"var(--hrm_palette-blue-purple)"}
						direction={"left"}
						width={"280px"}
						extraParam={data?.productId}
					/>
					:null}
				</div>}
			</div>
			<div className="tr_bar tr_bar_15 centerBx">
				{parseFloatToDecimal(data?.qty,2)}
			</div>
			<div className="tr_bar tr_bar_15 centerBx">
				{data?.profile}
			</div>

		</div>
	)

}










