 const filterLocation = (l,v) =>{
	let nA = [];
	l && l.map(fl=>{
		
		if(fl.label.indexOf(v)>=0){
			nA.push(fl);
		}
	})
	return nA;
 }



 const filterLocationIndex = (l,key,id) =>{
	let indx = null;
	l && l.map((fl, inX)=>{
		
		if(fl[key]===id){
			indx =  inX;
		}
	})
	return indx;
 }
