
import React, { useState, useEffect } from "react";


import "../component/dashboard.css"
import "../component/styles.css"
import {  TextInput_Cmpt, TimePickerDrop_Cmpt, CheckBoxSlide_Cmpt, TimePickerWrapper_Cmpt, DropDwnPicker_Cmpt} from "../../../components";
import {  gen16CodeId,  getStore, updStore, ObjectKeys } from "../../../stores/Utils";
import { CloseModal } from "../../../components/DialogHRM";
import { LeftLShapeScketch, UShapeScketch } from "./Typesframes";




const BluePrintModal  = ({
	data,
	wT, hT, svDm,
	vertice,
	item,
	comp2Render,
	confirm,
	disable
 }) => {

	
	const [, set_obs] = useState(1);


	useEffect(() => {
		set_obs(gen16CodeId())
	},[vertice]);


	const addBlPr = (frm2) => {
		confirm(frm2);
		close();
	}


	const close  = ()  => {
		data?.modalID && CloseModal({id:data?.modalID});
	}



	const Cmp2Rend = {
		"LL": <LeftLShapeScketch item={item} wT={wT} hT={hT} svDm={item?.bluePrint} addBlPr={addBlPr} profile={item?.profile} disable={disable} />,
		"U":<UShapeScketch item={item} wT={wT} hT={hT} svDm={item?.bluePrint} addBlPr={addBlPr}  profile={item?.profile}  disable={disable}/>
	}


	


	
    return (
		<div style={{
			maxHeight: "86vh",
			minHeight: "65vh",
			width: "960px",
			overflow: "auto",
			background: "var(--hrm_palette-general-background-b)",
			
			borderRadius: 13,
			padding: "10px 19px"
		}}>
			{Cmp2Rend[comp2Render]}
		</div>

    )   
}



export default BluePrintModal;



const isValidB  = (advanceFilters, frm2)  => {
	let vld = 0;
	ObjectKeys(advanceFilters).map(ffa=>{
		let sft = frm2?.start || 0;
		let eft = frm2?.end || 0;
		let st = ffa.split("_")[0];
		let et = ffa.split("_")[1];
		if((sft >= st && sft <= et) || (eft >= st && eft <= et) ){
			vld = 1;
		}
	})
	return !vld && frm2?.minimunPay && frm2?.minimunPayByHour;
}



